"""Update the READMEs and the proof index for the final title and the six-sensor controller.  python update_readmes.py"""
import os, csv, json, shutil
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.abspath(os.path.join(HERE, '..', '..')); RES = os.path.join(HERE, 'results')
T = 'Agrovoltaic Canopy for Protection and Sustainable Farming'
n = {r['strategy']: r for r in json.load(open(os.path.join(RES, 'accuracy_summary.json')))['results']}
nn = n['SRMC-SC (noisy sensors)']; sc = n['Monthly schedule (SRMC-DT)']; f45 = n['Fixed 45 deg']
def rd(p): return open(os.path.join(ROOT, p), encoding='utf-8-sig').read()
def wr(p, t):
    full = os.path.join(ROOT, p); d = os.path.join(os.path.dirname(full), '_before_update'); os.makedirs(d, exist_ok=True)
    if not os.path.exists(os.path.join(d, os.path.basename(full))): shutil.copy(full, d)
    open(full, 'w', encoding='utf-8').write(t)
SUMMARY = ('Year-long test with noisy sensors (864 cases): %.1f %% of the best possible combined score (50 %% electricity + 50 %% crop light value); electricity %.0f %% and crop light %.0f %% of the best. Monthly plan %.1f %%, fixed 45 deg %.1f %%. MATLAB and the web twin make identical decisions (40 of 40).' % (nn['J_efficiency_pct'], nn['pv_index_pct'], nn['crop_index_pct'], sc['J_efficiency_pct'], f45['J_efficiency_pct']))
# ---- root README
t = rd('README.md').replace('# SRMC final-year project: review folders', '# %s: review folders' % T)
t = t.replace('Fully computer-based study of a wire-driven agrivoltaic canopy', 'Fully computer-based study of a six-sensor agrovoltaic canopy (pyranometer, PAR, DHT11, soil moisture, rain sensor tilt the panels to optimise crop light and electricity; a gutter harvests rain). It is a wire-driven canopy')
t += '\n\n## Proof folder\n\n`Proof/` holds a copy of every file a judge may ask for, a Q and A with the file that answers each question (`Proof/00_START_HERE.html`), the dataset sources (`01_Data_and_Sources/DATASET_SOURCES.md`) and an evidence-status table (real, validated, simulated or assumed). Old backups and scratch files are in `_archive/`.\n\n## Update 2026-10-25: six-sensor controller\n\n- Title: **%s**. Main idea: six sensors decide the panel tilt; the goal is to optimise crop light AND electricity.\n- Code, test and results: `Review4_Control_and_Simulation/sensor_controller/` (controller, year-long accuracy test, cross-check, twin patch). %s\n- The final live twin is `Review3_Digital_Twin/results/live_twin/SRMC_Digital_Twin.html` (six-sensor controller ON by default). Serve it with `python -m http.server 8765` in this folder.\n- `_project_core/` was restored with only the design file and data files so the MATLAB scripts run (they read `../_project_core/design` and `../_project_core/data`).\n- Hardware after the strength check: 10 kN winch, 6 mm SS316 drive wire, M24 turnbuckles, bigger anchors (see Review1 documents).\n' % (T, SUMMARY)
wr('README.md', t)
# ---- Review4
t = rd('Review4_Control_and_Simulation/README.md')
t = t.replace('# Review 4 - Control algorithm and simulation results', '# Review 4 - Six-sensor control algorithm and simulation results')
t = t.replace('**Goal.** Show how the panels are controlled (flat in rain, tilt stop otherwise) and what the controller gains compared with fixed designs.', '**Goal.** Show how six sensors (pyranometer, PAR, DHT11, soil moisture, rain, anemometer) control the tilt to optimise crop light and electricity, how close it gets to the optimum, and what it gains over fixed designs.')
t = t.replace('- The controller optimises on the physics model; it does not use live sensor feedback in this study.', '- The six-sensor controller reads simulated sensors (sliders and climate data) in the twin and Simulink; Review 0 reads real DHT11, soil and rain on an ESP board. Pyranometer and PAR have not been measured.\n- The combined score is the controller\'s own objective, so it shows how well the sensors reproduce the optimum, not crop yield.')
t += '\n\n## Update 2026-10-25: six-sensor controller (SRMC-SC)\n\n**Rule.** Rain wet = flat roof 3 deg; pyranometer below 20 W/m2 = night park 15 deg; otherwise try every angle 15 to 60 deg (0.5 deg) and pick the best J = 0.5 PV/PVmax + 0.5 crop/cropmax. PAR corrects the modelled crop light (ratio 0.7 to 1.3); DHT11 VPD and soil moisture give a stress that lowers the light the crop needs; hysteresis 2 % protects the motor. The hourly plan (SRMC-DT) stays as the planner and the fallback.\n\n**Result.** @SUMMARY@\n\n| Strategy | Electricity % of best | Crop light value % of best | Combined score % |\n|---|---|---|---|\n'.replace('@SUMMARY@', SUMMARY)
for r in json.load(open(os.path.join(RES, 'accuracy_summary.json')))['results']: t += '| %s | %.1f | %.1f | %.1f |\n' % (r['strategy'], r['pv_index_pct'], r['crop_index_pct'], r['J_efficiency_pct'])
t += '\n**Safety and water link.** `makeSafe` in `sensor_controller.js` adds fallbacks for the soil probe and rain sensor, move limits (120 s, 12 an hour, 900 deg a day) and a motor wear count (`test_safety.js`, 8 tests, `results/safety_tests.md`); `irrigation.js` and `irrigation_study.js` let the soil probe decide irrigation and show the water saved against a timer (`results/T16_irrigation_probe_vs_timer.csv`).\n**Files.** `sensor_controller/sensor_controller.js` (the controller), `sensor_controller/eval_sensor_controller.js` (year-long test), `matlab/srmc_sensor_controller.m` + `matlab/srmc_sc_crosscheck.m` (MATLAB version and cross-check), `matlab/build_simulink_sensor_controller.m` + `matlab/sl_sc_step.m` (Simulink), `sensor_controller/eval_accuracy_v2.js` (accuracy, noise, fault and yield study), `matlab/srmc_sc_accuracy.m` (accuracy in MATLAB), `results/tables/T11_accuracy_v2.csv` to `T15_accuracy_matlab.csv`, `results/figures/fig_accuracy_both_goals.png`, `results/simulink/srmc_sensor_controller_model.slx`.\n\n**Reproduce.** `node sensor_controller/eval_sensor_controller.js` (about 25 s); `node sensor_controller/make_crosscheck_cases.js` then MATLAB `srmc_sc_crosscheck`; MATLAB `build_simulink_sensor_controller`; `python sensor_controller/patch_twin.py` rebuilds the twin from the saved original.\n\n**Honest limits.** Simulated sensors; noise model assumed (pyranometer 5 %, PAR 5 %, DHT11 +-2 C / +-5 % RH, soil +-3 %); wind stow needs the 45 deg offset lever arm (design change; the twin mechanism animation still shows the original arm); the combined score is the controller own objective.\n'
wr('Review4_Control_and_Simulation/README.md', t)
# ---- Review3
t = rd('Review3_Digital_Twin/README.md').replace('# Review 3 - Digital twin', '# Review 3 - Digital twin of the six-sensor agrovoltaic canopy')
t += '\n\n## Update 2026-10-25\n\n- The twin is titled **%s** and runs the six-sensor controller by default (checkbox in the controller panel under the 3D view). Sliders: cloud cover, DHT11 temperature and humidity, soil moisture; the rain button is the rain sensor; a decision trace shows why each angle was chosen.\n- %s\n- Original twin (before this update) is kept in `results/live_twin/_old/`.\n- Accuracy scorecard (`documents/SRMC_Accuracy_Scorecard.html`) now includes the controller test. The sensor values are simulated.\n' % (T, SUMMARY)
wr('Review3_Digital_Twin/README.md', t)
# ---- Review1
t = rd('Review1_Design_and_CAD/README.md').replace('# Review 1 - Design, structure and CAD', '# Review 1 - Design, structure and CAD of the agrovoltaic canopy')
t += '\n\n## Update 2026-10-25: hardware after the strength check\n\n- Wire, joints, poles and motor were checked (`documents/SRMC_Component_Strength_Table.docx`). Carrier rope 0.37, stay 0.30, tube 0.76, bearings 0.37, column 0.05 at 140 km/h: good.\n- Four weak items were changed in `design.json` (feasible preset), the parts list and the DXF notes: drive wire 4 mm -> 6 mm SS316 7x19, winch 3 kN -> 10 kN (about 0.25 kW), turnbuckle M16 -> M24 (>= 72 kN), anchors -> screw/rock or 1.6 m3 buried concrete (the old block resisted 6.6 kN of 26 kN).\n- 8-panel set (4.4 kWp): weights, installation steps and cost in `documents/SRMC_8Panel_Guide_and_Cost.docx`, `SRMC_8Panel_Installation_Spec.html`, `8panel_BOM.csv`; generator `code_reference/build_hardware_docs.py`. Cost mid about INR 7.2 lakh, indicative.\n- Wind stow: anemometer plus a 45 deg offset lever arm (the plain arm has no lever at 90 deg).\n- Drawings and animations are regenerated for the final design: `results/cad_drawings/` (plan, elevation with anemometer mast and 90 deg stow, section and wire drive with the offset arm, parts list), `results/mechanism/mechanism_closeup.gif` and `mechanism_tilt.gif` (generators: `code_reference/derive_final_dxf.py` then `make_dxf_final.py`, and `make_mech_gifs.py`). The guide-pulley GIF and the Blender renders are from the first design.\n'
wr('Review1_Design_and_CAD/README.md', t)
# ---- Review5
t = rd('Review5_Economics_and_Final/README.md').replace('# Review 5 - Economics, farmer income and final conclusions', '# Review 5 - Economics, farmer income and final conclusions: %s' % T)
t += '\n\n## Update 2026-10-25\n\n- Title and wording changed to **%s**; the report has a new section 6A (six-sensor controller and accuracy); viva Q&A and expo playbook have new questions and numbers; poster, judge summary, results sheet and accuracy scorecard are updated and self-contained.\n- Electricity cost: about INR 6 to 7 per kWh with interest (`results/figures/lcoe_vs_tariff.png`), near the Tamil Nadu industrial grid charge (INR 7.50, Mercom India), above utility solar auctions (INR 2 to 2.6).\n- %s\n' % (T, SUMMARY)
wr('Review5_Economics_and_Final/README.md', t)
# ---- Review0 / Review2 titles
LOG = '\n## Update 2026-10-25: real-data logging\n\n`data_logging/` logs the sensors for a week and scores the week with the six-sensor controller: fake week for rehearsal now (`run_fake_week.bat`), real ESP32 data later (`run_real_week.bat`, firmware `SRMC_ESP32_six_sensors`). See `data_logging/README.md`. Not tested on hardware.\n'
for rel in ['Review0_Prototype_Demo/README.md', 'Review2_Solar_and_Shadow/README.md']:
    t = rd(rel)
    if 'Agrovoltaic Canopy for Protection' not in t: wr(rel, t + '\n\nProject title: **%s**.\n' % T + (LOG if 'Review0' in rel else ''))
# ---- proof index
rows = [('R6', 'Six-sensor controller: year-long test with noisy sensors, %.1f %% of the best combined score (electricity %.0f %%, crop light %.0f %%)' % (nn['J_efficiency_pct'], nn['pv_index_pct'], nn['crop_index_pct']), 'Review4_Control_and_Simulation/results/tables/T9_sensor_controller_accuracy.csv; results/figures/fig_accuracy_both_goals.png', 'node sensor_controller/eval_sensor_controller.js'),
        ('R6', 'MATLAB and the web twin make the same decisions (40 of 40 random sensor states)', 'Review4_Control_and_Simulation/results/crosscheck_sensor_controller_matlab_vs_js.txt', 'node sensor_controller/make_crosscheck_cases.js; MATLAB: srmc_sc_crosscheck'),
        ('R6', 'Simulink six-sensor controller on a test day (cloud, rain, dry soil)', 'Review4_Control_and_Simulation/results/simulink/srmc_sensor_controller_model.slx; sensor_controller_day.png; sensor_controller_log.csv', 'MATLAB: build_simulink_sensor_controller'),
        ('R6', 'Accuracy repeated in MATLAB (142 cases, same readings): 99.5 % of the best combined score, tilt error 3.4 deg', 'Review4_Control_and_Simulation/results/tables/T15_accuracy_matlab.csv; results/figures/fig_matlab_accuracy.png', 'node sensor_controller/make_accuracy_cases.js; MATLAB: srmc_sc_accuracy'),
        ('R6', 'Accuracy vs noise, faulty PAR sensor, and yield and rupees (v1 vs v2)', 'Review4_Control_and_Simulation/results/tables/T12_noise_sweep.csv; T13_fault_test.csv; T14_yield_and_money.csv; results/figures/fig_noise_fault.png; fig_yield_money.png', 'node sensor_controller/eval_accuracy_v2.js'),
        ('R0', 'Real-data logging: six-sensor ESP32 firmware, logger, fake-week rehearsal and weekly self-scoring', 'Review0_Prototype_Demo/data_logging/README.md; Review0_Prototype_Demo/data_logging/score_week_fake/week_report.html', 'data_logging/run_fake_week.bat (rehearsal); run_real_week.bat (real)'),
        ('R3', 'Mechanism animations and drawings regenerated for the final design (offset lever arm, 6 mm wire, anemometer stow)', 'Review1_Design_and_CAD/results/mechanism/mechanism_closeup.gif; Review1_Design_and_CAD/results/mechanism/mechanism_tilt.gif; Review1_Design_and_CAD/results/cad_drawings/SRMC_feasible_elevation.dxf', 'python code_reference/make_mech_gifs.py; derive_final_dxf.py; make_dxf_final.py'),
        ('R6', 'Controller safety: sensor-failure fallbacks (rain, soil), move limits, motor wear count (8 tests pass)', 'Review4_Control_and_Simulation/results/safety_tests.md', 'node sensor_controller/test_safety.js'),
        ('R5', 'Water link: soil probe decides irrigation; 4.8 % water saved and no stress days against a timer; probe faults and fallback', 'Review4_Control_and_Simulation/results/tables/T16_irrigation_probe_vs_timer.csv; results/figures/fig_irrigation_probe_vs_timer.png', 'node sensor_controller/irrigation_study.js'),
        ('All', 'Proof folder with data sources, evidence status and judge Q and A', 'Proof/00_START_HERE.html', 'python Review5_Economics_and_Final/code_reference/build_proof.py'),
        ('R5', 'Digital twin runs the six-sensor controller by default (sensor card, sliders, decision trace)', 'Review3_Digital_Twin/results/live_twin/SRMC_Digital_Twin.html', 'python -m http.server 8765 (open the twin)'),
        ('R3', 'Strength of wire, joints, poles and motor; weak items changed (winch 10 kN, 6 mm drive wire, M24 turnbuckles, anchors)', 'Review1_Design_and_CAD/documents/SRMC_Component_Strength_Table.docx; results/structure/wind_sweep_feasible.png', 'python code_reference/build_hardware_docs.py'),
        ('R3', '8-panel set (4.4 kWp): weights, installation steps and indicative cost', 'Review1_Design_and_CAD/documents/SRMC_8Panel_Guide_and_Cost.docx; 8panel_BOM.csv', 'python code_reference/build_hardware_docs.py'),
        ('R7', 'Cost of electricity about INR 6 to 7 per kWh vs tariffs (Mercom, SECI)', 'Review5_Economics_and_Final/results/figures/lcoe_vs_tariff.png; results/tables/lcoe_table.csv', 'assumption-based (capex INR 60,000/kWp, 25 years)')]
pd = 'Review5_Economics_and_Final/documents/proof_and_references/'
t = rd(pd + 'PROOF_INDEX.md'); k = len([l for l in t.splitlines() if l.startswith('| ')]) - 1
for i, (rv, cl, ev, rp) in enumerate(rows, 1):
    ok = all(os.path.exists(os.path.join(ROOT, e.strip().split(' ')[0] if e.strip().startswith('Review') else e.strip())) for e in ev.split(';') if e.strip().startswith('Review'))
    t += '| %d | %s | %s | %s | `%s` | %s |\n' % (k + i, rv, cl, ev, rp, 'yes' if ok else 'check')
wr(pd + 'PROOF_INDEX.md', t.replace('# Proof index', '# Proof index (%s)' % T, 1))
c = rd(pd + 'PROOF_INDEX.csv'); kk = len(c.strip().splitlines()) - 1
d_ = os.path.join(ROOT, pd, '_before_update'); os.makedirs(d_, exist_ok=True); shutil.copy(os.path.join(ROOT, pd, 'PROOF_INDEX.csv'), d_) if not os.path.exists(os.path.join(d_, 'PROOF_INDEX.csv')) else None
with open(os.path.join(ROOT, pd, 'PROOF_INDEX.csv'), 'a', newline='', encoding='utf-8') as f:
    w2 = csv.writer(f)
    for i, (rv, cl, ev, rp) in enumerate(rows, 1): w2.writerow([kk + i, rv, cl, ev, rp])
print('readmes and proof index updated')
